'use client';

/**
 * Generated pictures for typed words, on paid plans.
 *
 * Built-in phrases never come here: they show a bundled symbol or their word
 * (lib/builtInSymbols.ts). What reaches this module is a custom phrase or a
 * predicted word that is not built-in vocabulary. Free and anonymous users see
 * those as words, so no request is made for them at all; paid subscribers get
 * a flat-vector pictogram generated by the Synalux portal.
 *
 * Results are cached in IndexedDB by version, language, mode and the full
 * normalized concept. Qualifiers such as "computer mouse" stay in the key.
 */

import { PictureMode } from '@/store/settingsStore';
import { SynaluxProfile } from '@/services/aiService';
import { SYNALUX_API, timeoutSignal } from '@/lib/portalConfig';
import { containsProfanity, containsSensitive } from '@/engine/ageBlocklist';
import { PictogramQueue, PicturePendingError, PICTURE_RETRY_DELAY_MS, PICTURE_MAX_RETRY_DELAY_MS } from '@/services/pictogramQueue';
export { PicturePendingError } from '@/services/pictogramQueue';
export { clearLegacyPictogramCache } from '@/services/legacyPictogramCache';

/**
 * Picture mode is derived from the user's Synalux plan, not from a user
 * preference. Free signed-in users get the bundled symbols and see typed
 * words as words; paid subscribers (Standard / Advanced / Enterprise)
 * additionally get generated pictures for typed words.
 *
 * A null profile means anonymous or still loading, so it must stay on the
 * free path. Optimistically calling the paid route caused a burst of 401s for
 * every anonymous first visit. Paid profile hydration changes the mode to
 * `symbols-ai`, which is part of the cache key.
 */
export function pictureModeForProfile(profile: SynaluxProfile | null): PictureMode {
  if (!profile || profile.plan === 'free') return 'symbols';
  return 'symbols-ai';
}

/** Whether a typed word can get a generated picture in this mode. */
export function typedWordPicturesEnabled(mode: PictureMode): boolean {
  return mode === 'symbols-ai';
}

const STYLE_VERSION = 3;
// Part of the cache key. Version 3 started a new database: everything cached
// before it, including third-party pictograms, stays out of the lookup.
const CACHE_VERSION = 4;
const MAX_IMAGE_BYTES = 2 * 1024 * 1024; // 2MB cap — prevents OOM from oversized blobs
// Large enough to hold a full vocabulary board without eviction.
// We do NOT revoke on eviction — a PhraseTile component may still hold
// the old blob URL in its iconUrl state and revoking causes
// WebKitBlobResource error 1. Blob URLs are cleaned up by the browser
// when the page unloads; the memory cost is negligible.
const MAX_MEM_CACHE = 600;
const MISS_CACHE_TTL_MS = 30_000;
// The portal answers "no new pictures" while generation is switched off; a
// word that misses then stays a word for this long before it is asked again.
const GENERATION_OFF_MISS_TTL_MS = 30 * 60_000;
const MEM_CACHE = new Map<string, { url: string | null; expiresAt: number }>();
type Flight = { promise: Promise<string | null>; consumers: Set<symbol>; cancelQueued?: () => boolean; discarded?: boolean };
const IN_FLIGHT = new Map<string, Flight>();
const GENERATION_QUEUE = new PictogramQueue();
const POLL_INTERVAL_MS = 500;
const POLL_TIMEOUT_MS = 35_000;
type CloudPicture = { kind: 'image'; blob: Blob } | { kind: 'pending'; pollToken?: string }
  | { kind: 'miss'; generationOff?: boolean } | { kind: 'unavailable'; transient?: boolean; retryAfterMs?: number };

function memCacheSet(key: string, value: string | null, missTtlMs = MISS_CACHE_TTL_MS) {
  if (MEM_CACHE.size >= MAX_MEM_CACHE) {
    const oldest = MEM_CACHE.keys().next().value;
    if (oldest !== undefined) MEM_CACHE.delete(oldest);
    // No URL.revokeObjectURL — component may still hold the old URL.
  }
  MEM_CACHE.set(key, { url: value, expiresAt: value ? Infinity : Date.now() + missTtlMs });
}

async function sha256(input: string): Promise<string> {
  const enc = new TextEncoder().encode(input);
  const hash = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function words(phrase: string): string[] {
  return phrase
    .toLowerCase()
    // Keep combining marks: Devanagari, Bengali and Amharic vowel signs are marks, and dropping them turns a listed word
    // into a different, unlisted one (चूतिया -> चतय).
    .replace(/[^\p{L}\p{M}\p{N}\s]/gu, '')
    .trim()
    .split(/\s+/)
    .filter(Boolean);
}

// ── IndexedDB cache ─────────────────────────────────────────────────────────

const DB_NAME = 'prism-aac-generated-pictures';
const STORE = 'blobs';
let dbPromise: Promise<IDBDatabase> | null = null;

function openDb(): Promise<IDBDatabase> {
  if (typeof window === 'undefined') return Promise.reject(new Error('no window'));
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return dbPromise;
}

async function cacheGet(key: string): Promise<Blob | null> {
  try {
    const db = await openDb();
    return await new Promise<Blob | null>((resolve, reject) => {
      const tx = db.transaction(STORE, 'readonly');
      const req = tx.objectStore(STORE).get(key);
      req.onsuccess = () => resolve((req.result as Blob | undefined) ?? null);
      req.onerror = () => reject(req.error);
    });
  } catch {
    return null;
  }
}

async function cachePut(key: string, blob: Blob): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(blob, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } catch { /* eviction / quota — best effort */ }
}

// ── Synalux AI ──────────────────────────────────────────────────────────────

async function fetchSynaluxAI(phrase: string, lang: string, cacheOnly: boolean, pollToken?: string): Promise<CloudPicture> {
  const t = timeoutSignal(cacheOnly ? 10_000 : 60_000);
  try {
    const res = await fetch(`${SYNALUX_API}/prism-aac/pictogram/v3${cacheOnly ? '?cacheOnly=1' : ''}`, {
      method: 'POST',
      // 'same-origin': credentials sent to synalux.ai but NOT on cross-origin
      // redirects to supabase.co (which returns ACAO:* — incompatible with
      // credentials:include and triggers a browser CORS block).
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        phrase: phrase.slice(0, 100),
        lang,
        style: 'aac-pictogram',
        styleVersion: STYLE_VERSION,
        ...(pollToken ? { pollToken } : {}),
      }),
      signal: t.signal,
    });
    if (res.status === 202) {
      const data = await res.json();
      return { kind: 'pending', pollToken: typeof data.pollToken === 'string' ? data.pollToken : undefined };
    }
    const protocol = (res.status === 404 || res.status === 429) && res.headers.get('content-type')?.includes('application/json')
      ? await res.json() as { styleVersion?: number; retryAfter?: number; generation?: boolean } : null;
    // Generation is switched off on the portal: a final miss, never retried and
    // never followed by a request for a new picture.
    if (res.status === 404 && (res.headers.get('X-AAC-Picture-Generation') === 'off' || protocol?.generation === false)) {
      return { kind: 'miss', generationOff: true };
    }
    if (res.status === 404 && cacheOnly && (res.headers.get('X-AAC-Picture-Version') === String(STYLE_VERSION)
      || protocol?.styleVersion === STYLE_VERSION)) return { kind: 'miss' };
    if (!res.ok) {
      console.warn(`[pictogram] Synalux AI returned ${res.status} for "${phrase}" (${lang})`);
      const retrySeconds = Number(res.headers.get('Retry-After') ?? protocol?.retryAfter);
      const retryAfterMs = Number.isFinite(retrySeconds) && retrySeconds > 0
        ? Math.min(PICTURE_MAX_RETRY_DELAY_MS, Math.max(PICTURE_RETRY_DELAY_MS, retrySeconds * 1_000))
        : PICTURE_RETRY_DELAY_MS;
      return { kind: 'unavailable', transient: res.status >= 500 || res.status === 404 || res.status === 429, retryAfterMs };
    }
    const ct = res.headers.get('content-type') || '';
    if (!ct.startsWith('image/')) {
      console.warn(`[pictogram] Synalux AI returned non-image content-type "${ct}" for "${phrase}"`);
      return { kind: 'unavailable' };
    }
    const cl = res.headers.get('content-length');
    if (cl && parseInt(cl, 10) > MAX_IMAGE_BYTES) {
      console.warn(`[pictogram] Synalux AI response too large (${cl} bytes) for "${phrase}"; skipping`);
      return { kind: 'unavailable' };
    }
    const blob = await res.blob();
    if (blob.size > MAX_IMAGE_BYTES) {
      console.warn(`[pictogram] Synalux AI blob too large (${blob.size} bytes) for "${phrase}"; skipping`);
      return { kind: 'unavailable' };
    }
    return { kind: 'image', blob };
  } catch (e) {
    console.warn(`[pictogram] Synalux AI fetch failed for "${phrase}":`, e instanceof Error ? e.message : e);
    return { kind: 'unavailable', transient: true };
  } finally {
    t.cancel();
  }
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * A generated picture for a typed word, or null to show the word.
 *
 * Null without any request when the plan has no generated pictures, and for
 * any phrase containing a word on the profanity or sensitive lists — those
 * are never sent for generation. `shown` is the phrase as the tile shows it
 * and its language, when generation uses another text (the English phrase):
 * a word listed in the shown language blocks the picture too, so Swahili
 * "tako" or Taiwan 幹 never reach generation through an English request.
 */
export async function getPictogramUrl(
  phrase: string,
  lang: string,
  mode: PictureMode,
  shown?: { text: string; lang: string },
  options?: { signal?: AbortSignal },
): Promise<string | null> {
  if (!typedWordPicturesEnabled(mode)) return null;
  const listed = (text: string, language: string) => containsProfanity(text, language) || containsSensitive(text, language);
  if (listed(phrase, lang) || (shown && listed(shown.text, shown.lang))) return null;
  if (!words(phrase).length || options?.signal?.aborted) return null;
  const meaning = phrase.normalize('NFC').trim().toLowerCase().replace(/\s+/gu, ' ').slice(0, 100);

  const key = await sha256(JSON.stringify([CACHE_VERSION, STYLE_VERSION, lang, mode, meaning]));
  if (options?.signal?.aborted) return null;
  let flight = IN_FLIGHT.get(key);
  if (!flight) {
    flight = { promise: Promise.resolve(null), consumers: new Set() };
    flight.promise = resolvePictogramUrl(meaning, lang, key, flight);
    IN_FLIGHT.set(key, flight);
    const current = flight;
    const cleanup = () => { if (IN_FLIGHT.get(key) === current) IN_FLIGHT.delete(key); };
    current.promise.then(cleanup, cleanup);
  }
  const current = flight;
  return new Promise<string | null>((resolve, reject) => {
    const consumer = Symbol();
    current.consumers.add(consumer);
    let settled = false;
    const finish = (value: string | null, error?: PicturePendingError) => {
      if (settled) return;
      settled = true;
      current.consumers.delete(consumer);
      options?.signal?.removeEventListener('abort', abort);
      if (error) reject(error);
      else resolve(value);
    };
    const abort = () => {
      finish(null);
      if (!current.consumers.size && current.cancelQueued?.()) {
        current.discarded = true;
        if (IN_FLIGHT.get(key) === current) IN_FLIGHT.delete(key);
      }
    };
    options?.signal?.addEventListener('abort', abort, { once: true });
    current.promise.then(finish, error => {
      if (error instanceof PicturePendingError && !settled) {
        finish(null, error);
      } else finish(null);
    });
  });
}

async function resolvePictogramUrl(phrase: string, lang: string, key: string, flight: Flight): Promise<string | null> {
  const entry = MEM_CACHE.get(key);
  if (entry && Date.now() < entry.expiresAt) return entry.url;
  if (entry) MEM_CACHE.delete(key);

  const cached = await cacheGet(key);
  if (cached) {
    const url = URL.createObjectURL(cached);
    memCacheSet(key, url);
    return url;
  }

  if (!flight.consumers.size) return null;
  const probe = await fetchSynaluxAI(phrase, lang, true);
  if (probe.kind === 'unavailable' && probe.transient) throw new PicturePendingError(probe.retryAfterMs);
  if (probe.kind === 'miss' && probe.generationOff) {
    if (!flight.discarded && flight.consumers.size) memCacheSet(key, null, GENERATION_OFF_MISS_TTL_MS);
    return null;
  }
  let blob: Blob | null = null;
  if (probe.kind === 'image') blob = probe.blob;
  else if (probe.kind === 'pending') blob = await awaitSharedPicture(phrase, lang, probe.pollToken);
  else if (probe.kind === 'miss' && flight.consumers.size) {
    const queued = GENERATION_QUEUE.enqueue(async () => {
      const generated = await fetchSynaluxAI(phrase, lang, false);
      if (generated.kind === 'image') return generated.blob;
      if (generated.kind === 'unavailable' && generated.transient) throw new PicturePendingError(generated.retryAfterMs);
      return generated.kind === 'pending' ? awaitSharedPicture(phrase, lang, generated.pollToken) : null;
    }, () => flight.consumers.size > 0);
    flight.cancelQueued = queued.cancel;
    blob = await queued.promise;
  }
  if (!blob) {
    if (!flight.discarded && flight.consumers.size) memCacheSet(key, null);
    return null;
  }
  await cachePut(key, blob);
  const url = URL.createObjectURL(blob);
  memCacheSet(key, url);
  return url;
}

async function awaitSharedPicture(phrase: string, lang: string, pollToken?: string): Promise<Blob | null> {
  const end = Date.now() + POLL_TIMEOUT_MS;
  while (Date.now() < end) {
    await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS));
    const picture = await fetchSynaluxAI(phrase, lang, true, pollToken);
    if (picture.kind === 'image') return picture.blob;
    if (picture.kind === 'unavailable' && picture.transient) throw new PicturePendingError(picture.retryAfterMs);
    if (picture.kind !== 'pending') return null;
    pollToken = picture.pollToken ?? pollToken;
  }
  throw new PicturePendingError();
}
